function solve(x){
  var s=x.state, a=s&&Array.isArray(s.m)?s.m:[], e=x.event, i, r;
  function cp(a,b){
    var x=Array.from(a),y=Array.from(b),n=Math.min(x.length,y.length),i,p,q;
    for(i=0;i<n;i++){p=x[i].codePointAt(0);q=y[i].codePointAt(0);if(p!==q)return p<q?-1:1}
    return x.length===y.length?0:(x.length<y.length?-1:1)
  }
  function better(a,b){
    var c;
    if(!b||a.version!==b.version)return !b||a.version>b.version;
    if(a.deleted!==b.deleted)return a.deleted;
    c=cp(a.actor,b.actor);if(c)return c>0;
    return cp(a.value,b.value)>0;
  }
  for(i=0;i<a.length;i++)if(a[i].key===e.key){if(better(e,a[i]))a[i]={key:e.key,version:e.version,actor:e.actor,deleted:e.deleted,value:e.value};break}
  if(i===a.length)a.push({key:e.key,version:e.version,actor:e.actor,deleted:e.deleted,value:e.value});
  function put(o,k,v){Object.defineProperty(o,k,{value:v,enumerable:true,writable:true,configurable:true})}
  var v={},t=[];
  for(i=0;i<a.length;i++){r=a[i];if(r.deleted)t.push(r.key);else put(v,r.key,r.value)}
  t.sort(cp);
  return {state:{m:a},output:{visible:v,tombstones:t}}
}
